#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from __future__ import annotations

import base64
import py_compile
import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path('/root/autodl-tmp')
TARGET = ROOT / 'main_tune.py'
FINAL_MARKER = 'SWE_FINETUNE_V2_FINAL_GUARD'

PATCH_1_B64 = ''
PATCH_2_B64 = ''
PATCH_3_B64 = ''


def _run_embedded(name: str, encoded: str) -> None:
    temp_dir = ROOT / '.swe_finetune_v2_patch_tmp'
    temp_dir.mkdir(parents=True, exist_ok=True)
    path = temp_dir / name
    source = base64.b64decode(encoded.encode('ascii')).decode('utf-8')
    source = source.replace(
        'ROOT = Path("/root/autodl-tmp")',
        f'ROOT = Path({str(ROOT)!r})',
    )
    source = source.replace(
        "ROOT = Path('/root/autodl-tmp')",
        f'ROOT = Path({str(ROOT)!r})',
    )
    path.write_text(source, encoding='utf-8')
    result = subprocess.run([sys.executable, str(path)], cwd=str(ROOT))
    if result.returncode != 0:
        raise RuntimeError(f'{name} 执行失败: {result.returncode}')


def _replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f'{label}: 期望匹配1次，实际{count}次')
    return text.replace(old, new, 1)


def _finalize() -> None:
    text = TARGET.read_text(encoding='utf-8')
    if FINAL_MARKER in text:
        py_compile.compile(str(TARGET), doraise=True)
        print('✅ main_tune.py 已包含 SWE 微调 V2 最终修复')
        return

    changes = []

    # 损失权重
    for old in ('"finetune_high_bias_weight": 0.3,', '"finetune_high_bias_weight": 0.30,'):
        if old in text:
            text = text.replace(old, '"finetune_high_bias_weight": 0.10,', 1)
            changes.append('high_bias_weight=0.10')
            break
    for old in ('"finetune_variance_weight": 0.01,', '"finetune_variance_weight": 0.02,'):
        if old in text:
            text = text.replace(old, '"finetune_variance_weight": 0.05,', 1)
            changes.append('std_ratio_weight=0.05')
            break
    text = text.replace('self.config.get("finetune_high_bias_weight", 0.3)', 'self.config.get("finetune_high_bias_weight", 0.10)')
    text = text.replace('self.config.get("finetune_variance_weight", 0.01)', 'self.config.get("finetune_variance_weight", 0.05)')
    text = text.replace('self.config.get("finetune_variance_weight", 0.02)', 'self.config.get("finetune_variance_weight", 0.05)')

    # 将旧绝对标准差差值升级为无量纲std-ratio。
    old_var = """            variance_loss = torch.relu(
                target_std_ratio * target_std - pred_std
            ).pow(2)
        else:
            target_std = torch.zeros((), device=error.device, dtype=error.dtype)
            pred_std = torch.zeros((), device=error.device, dtype=error.dtype)
            variance_loss = torch.zeros((), device=error.device, dtype=error.dtype)
"""
    new_var = """            if float(target_std.detach().item()) > 1e-8:
                std_ratio = pred_std / target_std.clamp_min(1e-8)
                # SWE_FINETUNE_V2_STD_RATIO_LOSS
                variance_loss = torch.relu(
                    torch.as_tensor(
                        target_std_ratio,
                        device=error.device,
                        dtype=error.dtype,
                    ) - std_ratio
                ).pow(2)
            else:
                std_ratio = torch.ones((), device=error.device, dtype=error.dtype)
                variance_loss = torch.zeros((), device=error.device, dtype=error.dtype)
        else:
            target_std = torch.zeros((), device=error.device, dtype=error.dtype)
            pred_std = torch.zeros((), device=error.device, dtype=error.dtype)
            std_ratio = torch.zeros((), device=error.device, dtype=error.dtype)
            variance_loss = torch.zeros((), device=error.device, dtype=error.dtype)
"""
    if old_var in text:
        text = text.replace(old_var, new_var, 1)
        changes.append('variance_to_std_ratio')

    if '"std_ratio": std_ratio.detach(),' not in text:
        old_diag = """            "pred_std": pred_std.detach(),
            "high_count": int(high_mask.sum().item()),
"""
        new_diag = """            "pred_std": pred_std.detach(),
            "std_ratio": std_ratio.detach(),
            "high_count": int(high_mask.sum().item()),
"""
        if old_diag in text:
            text = text.replace(old_diag, new_diag, 1)

    # 塌缩控制参数
    if '            "collapse_std_ratio_threshold":' not in text:
        anchor = '            "checkpoint_w_correlation": 0.05,\n'
        extra = (
            '            "checkpoint_w_correlation": 0.05,\n\n'
            '            # SWE_FINETUNE_V2_FINAL_GUARD\n'
            '            "collapse_std_ratio_threshold": 0.05,\n'
            '            "collapse_pred_std_mm_threshold": 1.0,\n'
            '            "collapse_max_rollbacks": 1,\n'
            '            "collapse_early_stop_patience": 2,\n'
        )
        text = _replace_once(text, anchor, extra, 'collapse defaults')
        changes.append('collapse_defaults')

    text = text.replace('self.config.get("collapse_std_ratio_threshold", 0.03)', 'self.config.get("collapse_std_ratio_threshold", 0.05)')
    text = text.replace('self.config.get("collapse_pred_std_mm_threshold", 0.50)', 'self.config.get("collapse_pred_std_mm_threshold", 1.0)')
    text = text.replace('self.config.get("collapse_max_rollbacks", 2)', 'self.config.get("collapse_max_rollbacks", 1)')

    # epoch-0状态
    init_old = """        best_epoch = 0
        collapse_rollbacks = 0

        # FINETUNE_EPOCH0_BASELINE_V1
"""
    init_new = """        best_epoch = 0
        best_val_r = -float("inf")
        collapse_rollbacks = 0
        collapse_streak = 0

        # FINETUNE_EPOCH0_BASELINE_V1
"""
    if init_old in text:
        text = text.replace(init_old, init_new, 1)
        changes.append('collapse_streak_state')

    # 连续塌缩计数
    old = """                    if is_collapsed:
                        patience_counter += 1
"""
    new = """                    if is_collapsed:
                        collapse_streak += 1
                        patience_counter += 1
"""
    if old in text:
        text = text.replace(old, new, 1)

    old = """                                print(
                                    f"   ↩ 已回滚到当前best并清空优化器状态；"
                                    f"学习率×0.2（第{collapse_rollbacks}/{max_rollbacks}次）"
                                )
                    elif is_better:
"""
    new = """                                print(
                                    f"   ↩ 已回滚到当前best并清空优化器状态；"
                                    f"学习率×0.2（第{collapse_rollbacks}/{max_rollbacks}次）"
                                )

                        collapse_limit = int(
                            self.config.get("collapse_early_stop_patience", 2)
                        )
                        if collapse_streak >= collapse_limit:
                            patience_counter = max(
                                patience_counter,
                                int(self.config.get("patience", 10)),
                            )
                            print(
                                f"   🛑 连续{collapse_streak}个验证epoch塌缩，"
                                "本折将在当前epoch后早停并恢复历史best"
                            )
                    elif is_better:
                        collapse_streak = 0
"""
    if old in text:
        text = text.replace(old, new, 1)
        changes.append('collapse_rollback_early_stop')

    guard_pos = text.find('# FINETUNE_COLLAPSE_GUARD_V1')
    if guard_pos >= 0:
        head, tail = text[:guard_pos], text[guard_pos:]
        old = """                    else:
                        patience_counter += 1
                        if verbose:
"""
        new = """                    else:
                        collapse_streak = 0
                        patience_counter += 1
                        if verbose:
"""
        if old in tail:
            tail = tail.replace(old, new, 1)
            text = head + tail

    # 修复sample_idx/source_flag诊断
    if 'FINETUNE_BATCH_DEBUG_SOURCE_FLAG_V1' not in text:
        old = """                    source_flag_debug = batch[5] if len(batch) > 5 else None

                    print(f"  batch 元素数量: {len(batch)}")
"""
        new = """                    # FINETUNE_BATCH_DEBUG_SOURCE_FLAG_V1
                    sample_idx_debug = batch[5] if len(batch) >= 6 else None
                    source_flag_debug = batch[6] if len(batch) >= 7 else None

                    print(f"  batch 元素数量: {len(batch)}")
"""
        if old in text:
            text = text.replace(old, new, 1)

        old = """                    if source_flag_debug is not None:
                        source_flag_debug = source_flag_debug.reshape(-1).long()
                        print(f"  source_flag 前10个: {source_flag_debug[:10]}")
                        print(f"  station样本数: {(source_flag_debug == 0).sum().item()}")
                        print(f"  pretrain样本数: {(source_flag_debug == 1).sum().item()}")
"""
        new = """                    if source_flag_debug is not None:
                        source_flag_debug = source_flag_debug.reshape(-1).long()
                        print(f"  source_flag 前10个: {source_flag_debug[:10]}")
                        print(f"  station样本数: {(source_flag_debug == 0).sum().item()}")
                        print(f"  pretrain样本数: {(source_flag_debug == 1).sum().item()}")
                    elif sample_idx_debug is not None:
                        sample_idx_debug = sample_idx_debug.reshape(-1).long()
                        print(f"  sample_idx 前10个: {sample_idx_debug[:10]}")
                        print("  当前为纯站点6元素batch，不包含source_flag")
"""
        if old in text:
            text = text.replace(old, new, 1)
            changes.append('fix_source_flag_debug')

    if FINAL_MARKER not in text:
        text = text.replace(
            '# FINETUNE_COLLAPSE_METRIC_V1',
            '# SWE_FINETUNE_V2_FINAL_GUARD\n        # FINETUNE_COLLAPSE_METRIC_V1',
            1,
        )

    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    backup_dir = ROOT / 'code_backups' / f'before_swe_finetune_v2_finalize_{stamp}'
    backup_dir.mkdir(parents=True, exist_ok=False)
    shutil.copy2(TARGET, backup_dir / TARGET.name)

    TARGET.write_text(text, encoding='utf-8')
    py_compile.compile(str(TARGET), doraise=True)

    required = [
        'PROGRESSIVE_CV_RELOAD_BEST_V1',
        'SWE_STRATIFIED_BATCH_SAMPLER_V1',
        'SIMPLIFIED_NSE_LOGCOSH_V1',
        'FINETUNE_HIGH_VALUE_METRICS_V1',
        'FINETUNE_STABLE_GROUPED_OPTIMIZER_V1',
        'FINETUNE_EPOCH0_BASELINE_V1',
        'FINETUNE_COLLAPSE_GUARD_V1',
        FINAL_MARKER,
    ]
    missing = [m for m in required if m not in text]
    if missing:
        raise RuntimeError(f'最终补丁标记缺失: {missing}')

    print('✅ SWE 微调 V2 最终修复完成')
    print(f'   changes={changes}')
    print(f'   backup={backup_dir / TARGET.name}')
    print(f'   target={TARGET}')


def main() -> None:
    if not TARGET.exists():
        raise FileNotFoundError(TARGET)

    current = TARGET.read_text(encoding='utf-8')
    if 'PROGRESSIVE_CV_RELOAD_BEST_V1' not in current:
        _run_embedded('01_best_checkpoint.py', PATCH_1_B64)

    current = TARGET.read_text(encoding='utf-8')
    if 'SIMPLIFIED_NSE_LOGCOSH_V1' not in current:
        _run_embedded('02_balanced_loss.py', PATCH_2_B64)

    current = TARGET.read_text(encoding='utf-8')
    if 'FINETUNE_COLLAPSE_GUARD_V1' not in current:
        _run_embedded('03_collapse_guard.py', PATCH_3_B64)

    _finalize()


if __name__ == '__main__':
    main()
